const row = $('Webhook').first().json.body;
const dealGeneral = $('Find Deal General').first().json.data;
// "Oficina recepción lead" = campo "Bank Mail / Email agente bancario" del deal bancario (si está vacío, el sub-workflow pone el código de oficina)
const bankDealId = String(row['Bank Deal ID'] || '').trim();
const bd = ($('Deal bancario (documento)').first().json || {}).data || {};
const bankDeal = String(bd.id || '') === bankDealId ? bd : {};   // sin Bank Deal ID no se usa ningún deal
const bm = String(bankDeal['498dd83b5c5e1f1181c232131933717ceadfda34'] || '').trim();
const bankMail = bm.includes('@') ? bm : '';
return [{ json: { dealGeneral, opportunityId: row['Opportunity ID'], nombreCliente: row['Nombre Cliente'], bankDealId, bankMail } }];

// Anti-duplicados: reserva el envío en el Command Center justo antes de mandar el correo al banco.
// Si este deal ya se envió a este banco en las últimas 6 h (p. ej. llegan ENVIAR + AUTORIZACION,
// o plataforma + hoja, para la misma fila), no se vuelve a enviar. force=true lo permite.
const row = $('Webhook').first().json.body || {};
const force = row.force === true || String(row.force || '').toLowerCase() === 'true';
let res;
try {
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: String($vars.COMMAND_CENTER_URL || 'https://banks-command-center.vercel.app').replace(/\/$/, '') + '/api/dossier/claim',
    headers: { 'x-offers-secret': $vars.OFFERS_API_SECRET, 'Content-Type': 'application/json' },
    body: {
      bank_slug: 'ibercaja',
      opportunity_id: row['Opportunity ID'],
      bank_deal_id: row['Bank Deal ID'] || null,
      workflow_id: $workflow.id,
      execution_id: $execution.id,
      source: row._source || row._ibercaja_action || null,
      force,
    },
    json: true,
    timeout: 20000,
  });
} catch (e) {
  throw new Error('Anti-duplicados: no se pudo comprobar el envío en el Command Center (' + (e.message || e) + '). No se envía para evitar duplicados.');
}
if (!res || res.allowed !== true) return [];   // ya enviado → se detiene esta rama sin mandar el correo
return $input.all();
